BOOL ov08_0221DAE4(BattleParty *battleParty);

BOOL ov08_0221DB04(BattleParty *battleParty);

u8 ov08_0221D5DC(BattleParty *battleParty, s32 partySlot);

u8 ov08_0221D5DC(BattleParty *battleParty, s32 partySlot) {
    if (battleParty->partyPokemon[partySlot].species == SPECIES_NONE) {
        return 0;
    }

    if (partySlot == 0 || (ov08_0221DAE4(battleParty) || ov08_0221DB04(battleParty)) && partySlot == 1) {
        return 1;
    }

    return 2;
}
